'<div class="amc-DTimeline-content">',
'  <h3 class="amc-DTimeline-title">#TITLE#</h3>',
'  {if ?BODY/}<p class="amc-DTimeline-body">#BODY#</p>{endif/}',
'</div>',
'{if ?DATE/}<span class="amc-DTimeline-date">#DATE#</span>{endif/}',
'{if ?TAG/}<span class="amc-DTimeline-tag">#TAG#</span>{endif/}',
'<span class="amc-DTimeline-level">{case STATE/}{when success/}Success{when warning/}Warning{when danger/}Error{when info/}Info{otherwise/}Note{endcase/}</span>'))
,p_default_escape_mode=>'HTML'
,p_translate_this_template=>true
,p_api_version=>1
,p_report_body_template=>'<div class="amc-DTimeline amc-DTimeline--#STYLE#"><ol class="amc-DTimeline-list">#APEX$ROWS#</ol></div>'
,p_report_row_template=>'<li class="amc-DTimeline-item amc-DTimeline-item--{case STATE/}{when success/}success{when warning/}warning{when danger/}danger{when info/}info{otherwise/}neutral{endcase/}">#APEX$PARTIAL#</li>'
,p_css_file_urls=>'#PLUGIN_FILES#amc-design-timeline.css'
,p_substitute_attributes=>true
,p_subscribe_plugin_settings=>true
,p_help_text=>'Each query row is one event, in the order the query returns them. Pick a Style for the whole region, then map Title (required), Body, Date, Icon, State and Tag to columns. Format dates in SQL with the application''s NLS settings. State accepts success, warning, danger, info or neutral; any other value renders as neutral.'
,p_version_identifier=>'1.0.0'
,p_files_version=>1
);
